// Applies the SQL migrations of drizzle/ (generated by `pnpm db:generate`), at the server's start and by `pnpm db:migrate`.
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { drizzle } from 'drizzle-orm/postgres-js';
import { migrate } from 'drizzle-orm/postgres-js/migrator';
import type postgres from 'postgres';

export const MIGRATIONS = join(dirname(fileURLToPath(import.meta.url)), '../../drizzle');

export async function runMigrations(sql: postgres.Sql) {
  await migrate(drizzle(sql), { migrationsFolder: MIGRATIONS });
}
